cat > "$TEMP/m.js" <<'EOF'
const fs=require('fs'),cp=require('child_process');
const files=cp.execSync('git diff --name-only 35179b0..2708c5a -- backend/src backend/evals/TutorFlow.Evals').toString().split('\n').filter(f=>f.endsWith('.cs'));
for(const f of files){
 let L;try{L=fs.readFileSync(f,'utf8').split('\n')}catch{continue}
 for(let i=0;i<L.length;i++){
  const l=L[i];
  if(!/^\s{4,12}(public|private|internal|static|protected)[^=;]*\)\s*$/.test(l)&&!/^\s{4,12}(public|private|internal|static)[^;]*\)\s*=>\s*$/.test(l))continue;
  if(/\b(class|record|struct|interface)\b/.test(l))continue;
  const ind=l.length-l.trimStart().length;
  let k=i+1;while(k<L.length&&!/^\s*[{]\s*$/.test(L[k])&&!/=>/.test(L[k])&&!/;\s*$/.test(L[k]))k++;
  let e,n;
  if(/^\s*\{\s*$/.test(L[k]||'')){e=k;while(e<L.length&&!(L[e].startsWith(' '.repeat(ind)+'}')&&L[e].length-L[e].trimStart().length==ind))e++;n=e-k-1;}
  else{e=k;while(e<L.length&&!/;\s*$/.test(L[e]))e++;n=e-i;}
  const body=L.slice(i,e+1).join('\n').replace(/"(\\.|[^"\\])*"/g,'""');
  const m=body.match(/\b(if|while|for|foreach|case|catch)\b|&&|\|\||\?\?|\s\?\s|\bor\b|\band\b/g)||[];
  const cc=1+m.length;
  if(n>20||cc>5)console.log(`${f}:${i+1} lines=${n} cc~${cc} ${l.trim().slice(0,70)}`);
 }
}
EOF
