namespace TutorFlow.Core.Autorizacion;

public static class DetectorAgregados
{
    private const int MaximoEntreSuperlativoYNota = 2;
    private const int MaximoEntrePosicionYVerbo = 3;
    private const int MaximoDeRellenoDelPromedio = 2;
    private const int MaximoDeRellenoDelListado = 3;
    private const int MaximoDeRellenoDelComparativo = 2;

    public static bool PideAgregados(string textoNormalizado)
    {
        var frases = new FrasesDelTexto(textoNormalizado);
        return NivelUno(frases) || NivelDos(frases);
    }

    private static bool NivelUno(FrasesDelTexto frases) =>
        frases.Contiene(VocabularioAgregados.FuertesSueltas)
        || PosicionPropia(frases)
        || PromedioDeColectivo(frases)
        || PluralSinPosesivo(frases);

    private static bool NivelDos(FrasesDelTexto frases) =>
        (frases.Contiene(VocabularioAgregados.Grupo) && NivelDosConGrupo(frases))
        || ConteoDeExistencia.Hay(frases);

    private static bool NivelDosConGrupo(FrasesDelTexto frases) =>
        SuperlativoSobreNota(frases)
        || Listado(frases)
        || frases.Contiene(VocabularioAgregados.VerbosDeListadoYResultado)
        || frases.ContieneRaiz(VocabularioAgregados.RaizDeComparar)
        || ComparativoSeguidoDeGrupo(frases);

    private static bool ComparativoSeguidoDeGrupo(FrasesDelTexto frases) =>
        frases.SeguidaDeRellenoY(
            VocabularioAgregados.Comparativos,
            VocabularioAgregados.RellenosDelComparativo,
            MaximoDeRellenoDelComparativo,
            VocabularioAgregados.Grupo);

    private static bool PosicionPropia(FrasesDelTexto frases) =>
        ProximidadDeFrases.Hay(
            frases.Ocurrencias(VocabularioAgregados.Posiciones),
            frases.Ocurrencias(VocabularioAgregados.VerbosDePosicion),
            MaximoEntrePosicionYVerbo);

    private static bool PromedioDeColectivo(FrasesDelTexto frases) =>
        frases.SeguidaDeRellenoY(
            VocabularioAgregados.PromediosDeGrupo,
            VocabularioAgregados.RellenosDelPromedio,
            MaximoDeRellenoDelPromedio,
            VocabularioAgregados.Colectivos);

    private static bool PluralSinPosesivo(FrasesDelTexto frases) =>
        !PreguntaPropia(frases)
        && ProximidadDeFrases.Hay(
            SinPosesivoAntes(frases, VocabularioAgregados.PluralesSuperlativos, VocabularioAgregados.PosesivoPlural),
            frases.Ocurrencias(VocabularioAgregados.NotasPlurales),
            MaximoEntreSuperlativoYNota);

    private static bool PreguntaPropia(FrasesDelTexto frases) =>
        frases.Contiene(VocabularioAgregados.Posesivos)
        && !frases.ContieneSeguidaDe(["mi"], VocabularioAgregados.Colectivos);

    private static bool SuperlativoSobreNota(FrasesDelTexto frases) =>
        ProximidadDeFrases.Hay(
            SinPosesivoAntes(frases, VocabularioAgregados.Superlativos, VocabularioAgregados.Posesivos),
            SinPosesivoAntes(frases, VocabularioAgregados.Notas, VocabularioAgregados.Posesivos),
            MaximoEntreSuperlativoYNota);

    private static bool Listado(FrasesDelTexto frases) =>
        frases.SeguidaDeRellenoY(
            VocabularioAgregados.Listadores,
            VocabularioAgregados.RellenosDelListado,
            MaximoDeRellenoDelListado,
            VocabularioAgregados.Grupo);

    private static IReadOnlyList<OcurrenciaDeFrase> SinPosesivoAntes(
        FrasesDelTexto frases,
        IEnumerable<string> vocabulario,
        IReadOnlyCollection<string> posesivos) =>
        [.. frases.Ocurrencias(vocabulario).Where(ocurrencia => !posesivos.Contains(frases.PalabraAntesDe(ocurrencia)))];
}
using TutorFlow.Core.Academico;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal sealed class AfirmacionesDeEstado
{
    private const int PalabrasHastaElVerbo = 2;
    private const string Motivo = "la afirmación de estado no coincide con los datos entregados";

    private static readonly HashSet<string> VerbosDeEstar = new(StringComparer.Ordinal) { "esta", "estas", "estan" };
    private static readonly HashSet<string> PalabrasQueAnulan = new(StringComparer.Ordinal) { "no", "ni", "sin" };
    private static readonly string[] EnPruebaAcademica = ["en", "prueba", "academica"];

    private readonly IReadOnlyList<AsignaturaCatalogo> _catalogo;

    public AfirmacionesDeEstado(IReadOnlyList<AsignaturaCatalogo> catalogo)
    {
        _catalogo = catalogo;
    }

    public string? Motivos(IReadOnlyList<BloqueDeTexto> bloques, ContextoDeAfirmaciones contexto)
    {
        var catalogo = CatalogoAsignaturas.Vigente(_catalogo, contexto.Directorio);
        return bloques.Select(bloque => MotivoDelBloque(bloque, catalogo, contexto)).FirstOrDefault(motivo => motivo is not null);
    }

    private static string? MotivoDelBloque(BloqueDeTexto bloque, IReadOnlyList<AsignaturaCatalogo> catalogo, ContextoDeAfirmaciones contexto)
    {
        var personas = contexto.PersonasDe(bloque);
        if (personas.Ambiguo)
        {
            return Exigencias(bloque.Texto, TokenizadorTexto.Tokenizar(bloque.Texto), catalogo).Count > 0 ? Motivo : null;
        }

        return personas.Tramos.Any(tramo => Exigencias(bloque.Texto, tramo.Tokens, catalogo).Any(exigencia => !contexto.Cumple(tramo.PersonaId, exigencia))) ? Motivo : null;
    }

    private static List<Func<ResumenEstudiante, bool>> Exigencias(string texto, IReadOnlyList<TokenTexto> tokens, IReadOnlyList<AsignaturaCatalogo> catalogo)
    {
        var palabras = tokens.Select(token => token.Valor).ToList();
        return [.. DeAprobacion(tokens, palabras, catalogo), .. DePruebaAcademica(texto, tokens)];
    }

    private static IEnumerable<Func<ResumenEstudiante, bool>> DeAprobacion(
        IReadOnlyList<TokenTexto> tokens,
        IReadOnlyList<string> palabras,
        IReadOnlyList<AsignaturaCatalogo> catalogo)
    {
        var formas = FormasDePerdida.Aprobaciones(palabras);
        return formas.Count == 0
            ? []
            : CatalogoAsignaturas.PrimerasApariciones(tokens, catalogo)
                .Where(nombrada => !FormasDePerdida.MasCercana(formas, nombrada).Negada)
                .Select(nombrada => EstaAprobada(nombrada.Clave));
    }

    private static Func<ResumenEstudiante, bool> EstaAprobada(string clave) =>
        resumen => resumen.Asignaturas.Any(resultado =>
            AmbitoPersonal.Clave(resultado.Asignatura.Codigo) == clave && resultado.Estado == EstadoAsignatura.Aprobada);

    private static IEnumerable<Func<ResumenEstudiante, bool>> DePruebaAcademica(string texto, IReadOnlyList<TokenTexto> tokens)
    {
        var palabras = tokens.Select(token => token.Valor).ToList();
        return Enumerable.Range(0, palabras.Count)
            .Where(indice => VerbosDeEstar.Contains(palabras[indice]) && SigueEnPruebaAcademica(palabras, indice) && !Anulada(texto, tokens, indice))
            .Select(_ => (Func<ResumenEstudiante, bool>)(resumen => resumen.PruebaAcademica));
    }

    private static bool SigueEnPruebaAcademica(List<string> palabras, int indice) =>
        indice + EnPruebaAcademica.Length < palabras.Count
        && EnPruebaAcademica.Select((palabra, desplazamiento) => palabras[indice + 1 + desplazamiento] == palabra).All(coincide => coincide);

    private static bool Anulada(string texto, IReadOnlyList<TokenTexto> tokens, int indice) =>
        indice > 0 && (PalabrasQueAnulan.Contains(tokens[indice - 1].Valor) || SiSinTilde(texto, tokens[indice - 1]) || ConCuandoCerca(tokens, indice) || EstudianteQue(tokens, indice));

    private static bool SiSinTilde(string texto, TokenTexto anterior) =>
        anterior.Valor == "si" && string.Equals(texto[anterior.Inicio..anterior.Fin], "si", StringComparison.OrdinalIgnoreCase);

    private static bool ConCuandoCerca(IReadOnlyList<TokenTexto> tokens, int indice) =>
        Enumerable.Range(Math.Max(0, indice - PalabrasHastaElVerbo - 1), PalabrasHastaElVerbo + 1).Any(posicion => tokens[posicion].Valor == "cuando");

    private static bool EstudianteQue(IReadOnlyList<TokenTexto> tokens, int indice) =>
        indice > 1 && tokens[indice - 1].Valor == "que" && tokens[indice - 2].Valor is "estudiante" or "estudiantes";
}
using System.Globalization;
using TutorFlow.Core.Academico;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal static class CamposLigados
{
    private const string Promedio = "promedio";
    private const int DecimalesDelPromedio = 2;
    private const string MotivoDeVoz = "escribe los datos del estudiante en tercera persona, con su nombre";

    public static string? Motivo(IReadOnlyList<BloqueDeTexto> bloques, ContextoDeAfirmaciones contexto) =>
        bloques.Select(bloque => MotivoDelBloque(bloque, contexto)).FirstOrDefault(motivo => motivo is not null);

    private static string? MotivoDelBloque(BloqueDeTexto bloque, ContextoDeAfirmaciones contexto)
    {
        var personas = contexto.PersonasDe(bloque);
        var tokens = TokenizadorTexto.TokenizarConCifras(bloque.Texto);
        return personas.Tramos.Select(tramo => MotivoDelTramo(bloque, tokens, tramo, contexto)).FirstOrDefault(motivo => motivo is not null)
            ?? (VozEquivocada(tokens, personas, contexto.Usuario) ? MotivoDeVoz : null);
    }

    private static string? MotivoDelTramo(BloqueDeTexto bloque, IReadOnlyList<TokenTexto> tokens, TramoDePersona tramo, ContextoDeAfirmaciones contexto)
    {
        if (!contexto.Resumenes.TryGetValue(tramo.PersonaId, out var resumen))
        {
            return null;
        }

        var inicios = tramo.Tokens.Select(token => token.Inicio).ToHashSet();
        var delTramo = tokens.Where(token => inicios.Contains(token.Inicio)).ToList();
        var cifra = PromedioQueNoCuadra(delTramo, resumen) ?? EnteroQueNoCuadra(bloque.Texto, delTramo, resumen);
        return cifra is null ? null : $"el valor {cifra} no coincide con los datos entregados";
    }

    private static string? PromedioQueNoCuadra(List<TokenTexto> tokens, ResumenEstudiante resumen) =>
        Enumerable.Range(0, tokens.Count)
            .Where(indice => tokens[indice].Valor == Promedio && !DefinitivaPorAsignatura.EstaNegada(tokens, indice))
            .Select(indice => DefinitivaPorAsignatura.CifraEfectiva(tokens, indice))
            .OfType<int>()
            .Select(posicion => tokens[posicion].Valor)
            .FirstOrDefault(cifra => !IgualAlPromedio(cifra, resumen.Promedio));

    private static bool IgualAlPromedio(string cifra, decimal? promedio) =>
        promedio is { } valor && decimal.Parse(cifra, CultureInfo.InvariantCulture) == CalculosAcademicos.Redondear(valor, DecimalesDelPromedio);

    private static string? EnteroQueNoCuadra(string texto, List<TokenTexto> tokens, ResumenEstudiante resumen)
    {
        var permitidos = EnterosDeAsistencia.De(resumen);
        return EnterosDeAsistencia.Candidatos(texto, tokens).FirstOrDefault(entero => !permitidos.Contains(entero));
    }

    private static bool VozEquivocada(IReadOnlyList<TokenTexto> tokens, PersonasDeBloque personas, Usuario usuario) =>
        usuario.Rol == Rol.Coordinador && personas is { Ambiguo: false, Tramos.Count: 0 } && VozDeTu.Hay(tokens);
}

