    private static readonly HashSet<string>[] SaltosPrevios = [new(StringComparer.Ordinal) { "nota", "calificacion" }, Determinantes, FormasDePerdida.Auxiliares];

    private readonly IReadOnlyList<AsignaturaCatalogo> _catalogo;

    public DefinitivaPorAsignatura(IReadOnlyList<AsignaturaCatalogo> catalogo)
    {
        _catalogo = catalogo;
    }

    public string? Motivo(
        IReadOnlyList<BloqueDeTexto> bloques,
        Usuario usuario,
        IReadOnlyCollection<string> idsAutorizados,
        DirectorioAcademico directorio,
        IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos)
    {
        var catalogo = CatalogoAsignaturas.Vigente(_catalogo, directorio);
        return bloques
            .SelectMany(bloque => Atribuciones(bloque, catalogo).Select(atribucion => (Bloque: bloque, Atribucion: atribucion)))
            .Select(par => MotivoDe(par.Atribucion, TramosDePersonas.De(par.Bloque, usuario, idsAutorizados, directorio), usuario, directorio, resumenesLeidos))
            .FirstOrDefault(motivo => motivo is not null);
    }

    public IEnumerable<(string Clave, string Cifra)> ParesDe(string respuesta, DirectorioAcademico directorio)
    {
        var catalogo = CatalogoAsignaturas.Vigente(_catalogo, directorio);
        return BloquesDeRespuesta.De(respuesta)
            .SelectMany(bloque => Atribuciones(bloque, catalogo))
            .Select(atribucion => (atribucion.Clave, atribucion.Cifra));
    }

    public bool SinCifrasNiAsignaturas(string respuesta, DirectorioAcademico directorio)
    {
        var catalogo = CatalogoAsignaturas.Vigente(_catalogo, directorio);
        return BloquesDeRespuesta.De(respuesta).All(bloque => SinCifrasNiAsignaturas(bloque, catalogo));
    }

    private static bool SinCifrasNiAsignaturas(BloqueDeTexto bloque, IReadOnlyList<AsignaturaCatalogo> catalogo)
    {
        var tokens = TokenizadorTexto.TokenizarConCifras(bloque.Texto);
        return CatalogoAsignaturas.Apariciones(tokens, catalogo).Count == 0
            && !Enumerable.Range(0, tokens.Count).Any(posicion => EsCifraDeNota(tokens, posicion));
    }

    private static string? MotivoDe(
        AtribucionDeDefinitiva atribucion,
        PersonasDeBloque personas,
        Usuario usuario,
        DirectorioAcademico directorio,
        IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos)
    {
        if (personas.Ambiguo)
        {
            return Motivo(atribucion, null, usuario, directorio);
        }

        return personas.Tramos
            .Where(tramo => tramo.Tokens.Any(token => token.Inicio == atribucion.InicioDeAsignatura))
            .Where(tramo => !Coincide(atribucion, tramo.PersonaId, resumenesLeidos))
            .Select(tramo => Motivo(atribucion, tramo.PersonaId, usuario, directorio))
            .FirstOrDefault();
    }

    private static string Motivo(AtribucionDeDefinitiva atribucion, string? personaId, Usuario usuario, DirectorioAcademico directorio)
    {
        var persona = personaId is null || usuario.Rol != Rol.Coordinador ? string.Empty : $" de {NombreDe(personaId, directorio)}";
        return $"la definitiva {atribucion.Cifra} de {atribucion.Escrita}{persona} no coincide con los datos entregados";
    }

    private static string NombreDe(string personaId, DirectorioAcademico directorio) =>
        directorio.Estudiantes.Select(estudiante => (estudiante.Id, estudiante.Nombre))
            .Concat(directorio.Coordinadores.Select(coordinador => (coordinador.Id, coordinador.Nombre)))
            .FirstOrDefault(persona => persona.Id == personaId).Nombre ?? personaId;

    private static IEnumerable<AtribucionDeDefinitiva> Atribuciones(BloqueDeTexto bloque, IReadOnlyList<AsignaturaCatalogo> catalogo)
    {
        var tokens = TokenizadorTexto.TokenizarConCifras(bloque.Texto);
        var apariciones = CatalogoAsignaturas.Apariciones(tokens, catalogo);
        var hayDefinitiva = Enumerable.Range(0, tokens.Count).Any(indice => EsDefinitiva(tokens, indice) && !EstaNegada(tokens, indice));
        var porCifra = Enumerable.Range(0, tokens.Count)
            .Where(indice => EsDefinitivaSingular(tokens, indice) && !EstaNegada(tokens, indice))
            .Select(indice => CifraEfectiva(tokens, indice))
            .OfType<int>()
            .SelectMany(cifra => AtribucionMasCercana(bloque, tokens, apariciones, cifra));
        return porCifra.Concat(Pares(bloque, tokens, apariciones, hayDefinitiva));
    }

    private static IEnumerable<AtribucionDeDefinitiva> AtribucionMasCercana(
        BloqueDeTexto bloque,
        IReadOnlyList<TokenTexto> tokens,
        IReadOnlyList<AparicionDeAsignatura> apariciones,
        int cifra)
    {
        var asignatura = AnteriorEnlazada(tokens, apariciones, cifra)
            ?? apariciones.MinBy(aparicion => (Distancia(aparicion, cifra), aparicion.Inicio > cifra));
        return asignatura is null ? [] : [Construir(bloque, tokens, asignatura, cifra, conDefinitiva: true)];
    }

    private static AparicionDeAsignatura? AnteriorEnlazada(
        IReadOnlyList<TokenTexto> tokens,
        IReadOnlyList<AparicionDeAsignatura> apariciones,
        int cifra)
    {
        var anterior = apariciones.Where(aparicion => aparicion.Fin < cifra).MaxBy(aparicion => aparicion.Fin);
        return anterior is not null && Enumerable.Range(anterior.Fin + 1, cifra - anterior.Fin - 1).All(posicion => PalabrasDeEnlace.Contains(tokens[posicion].Valor))
            ? anterior
            : null;
    }

    private static IEnumerable<AtribucionDeDefinitiva> Pares(
        BloqueDeTexto bloque,
        IReadOnlyList<TokenTexto> tokens,
        IReadOnlyList<AparicionDeAsignatura> apariciones,
        bool hayDefinitiva) =>
        apariciones
            .Where(aparicion => aparicion.Fin + 1 < tokens.Count && EsCifraDeNota(tokens, aparicion.Fin + 1) && SoloSeparadores(bloque.Texto, tokens, aparicion))
            .Where(aparicion => !EsUmbralDeCifra(tokens, aparicion.Fin + 1))
            .Select(aparicion => Construir(bloque, tokens, aparicion, aparicion.Fin + 1, hayDefinitiva));

    private static bool SoloSeparadores(string texto, IReadOnlyList<TokenTexto> tokens, AparicionDeAsignatura aparicion) =>
        SeparadoresDePar().IsMatch(texto[tokens[aparicion.Fin].Fin..tokens[aparicion.Fin + 1].Inicio]);

    private static AtribucionDeDefinitiva Construir(
        BloqueDeTexto bloque,
        IReadOnlyList<TokenTexto> tokens,
        AparicionDeAsignatura asignatura,
        int cifra,
        bool conDefinitiva) =>
        new(
            asignatura.Clave,
            tokens[cifra].Valor,
            tokens[asignatura.Inicio].Inicio,
            bloque.Texto[tokens[asignatura.Inicio].Inicio..tokens[asignatura.Fin].Fin],
            conDefinitiva);

    private static int Distancia(AparicionDeAsignatura asignatura, int cifra) =>
        asignatura.Fin < cifra ? cifra - asignatura.Fin : asignatura.Inicio - cifra;

    private static bool EsDefinitiva(IReadOnlyList<TokenTexto> tokens, int indice) =>
        tokens[indice].Valor == Definitivas || EsDefinitivaSingular(tokens, indice);

    private static bool EsDefinitivaSingular(IReadOnlyList<TokenTexto> tokens, int indice) =>
        tokens[indice].Valor == Definitiva || EsNotaFinal(tokens, indice);

    private static bool EsNotaFinal(IReadOnlyList<TokenTexto> tokens, int indice) =>
        tokens[indice].Valor == NotaFinal && indice > 0 && tokens[indice - 1].Valor is "nota" or "calificacion";

    internal static int? CifraEfectiva(IReadOnlyList<TokenTexto> tokens, int definitiva)
    {
        var cifra = CifraAsociada(tokens, definitiva);
        return cifra is { } asociada && EsUmbralDeCifra(tokens, asociada) ? SiguienteNoUmbral(tokens, asociada) : cifra;
    }

    private static int? SiguienteNoUmbral(IReadOnlyList<TokenTexto> tokens, int desde) =>
        Enumerable.Range(desde + 1, Math.Max(0, tokens.Count - desde - 1))
            .Where(posicion => EsCifraDeNota(tokens, posicion) && !EsUmbralDeCifra(tokens, posicion))
            .Select(posicion => (int?)posicion)
            .FirstOrDefault();

    private static bool EsUmbralDeCifra(IReadOnlyList<TokenTexto> tokens, int cifra) =>
        PrecedidaDeComparador(tokens, cifra) || SigueARequisito(tokens, cifra) || UmbralNormativo.Es(tokens, cifra);

    private static bool PrecedidaDeComparador(IReadOnlyList<TokenTexto> tokens, int cifra) =>
        TerminaComparador(tokens, cifra - 1) || (cifra > 0 && Enlaces.Contains(tokens[cifra - 1].Valor) && TerminaComparador(tokens, cifra - 2));

    private static bool TerminaComparador(IReadOnlyList<TokenTexto> tokens, int indice) =>
        indice >= 0
        && (Comparadores.Contains(tokens[indice].Valor)
            || (indice > 0 && ComparadoresDeDosPalabras.Contains((tokens[indice - 1].Valor, tokens[indice].Valor))));

    private static bool SigueARequisito(IReadOnlyList<TokenTexto> tokens, int cifra) =>
        RequisitoPrevio().IsMatch(string.Join(' ', tokens.Take(cifra).TakeLast(PalabrasDelRequisito).Select(token => token.Valor)));

    internal static bool EstaNegada(IReadOnlyList<TokenTexto> tokens, int indice)
    {
        var anterior = SaltosPrevios.Aggregate(indice - 1, (posicion, saltables) => Saltar(tokens, posicion, saltables));
        return anterior >= 0 && Negaciones.Contains(tokens[anterior].Valor);
    }

    private static int Saltar(IReadOnlyList<TokenTexto> tokens, int posicion, HashSet<string> saltables) =>
        posicion >= 0 && saltables.Contains(tokens[posicion].Valor) ? posicion - 1 : posicion;

    private static int? CifraAsociada(IReadOnlyList<TokenTexto> tokens, int indice)
    {
        var despues = Enumerable.Range(indice + 1, Math.Min(PalabrasHastaLaCifra, tokens.Count - indice - 1));
        var antes = Enumerable.Range(Math.Max(0, indice - PalabrasHastaLaCifra), Math.Min(PalabrasHastaLaCifra, indice)).Reverse();
        return despues.Concat(antes).Where(posicion => EsCifraDeNota(tokens, posicion)).Select(posicion => (int?)posicion).FirstOrDefault();
    }

    private static bool EsCifraDeNota(IReadOnlyList<TokenTexto> tokens, int posicion) =>
        CifraDeNota().IsMatch(tokens[posicion].Valor)
        && !(posicion > 0 && PalabrasDeReferencia.Contains(tokens[posicion - 1].Valor));

    private static bool Coincide(AtribucionDeDefinitiva atribucion, string personaId, IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos)
    {
        if (!resumenesLeidos.TryGetValue(personaId, out var resumen))
        {
            return true;
        }

        var resultado = resumen.Asignaturas.FirstOrDefault(r => AmbitoPersonal.Clave(r.Asignatura.Codigo) == atribucion.Clave);
        return resultado is null || ValoresAceptados(resultado, atribucion.ConDefinitiva).Contains(decimal.Parse(atribucion.Cifra, CultureInfo.InvariantCulture));
    }

    private static IEnumerable<decimal> ValoresAceptados(ResultadoAsignatura resultado, bool soloDefinitiva)
    {
        var definitiva = resultado.Estado == EstadoAsignatura.PerdidaPorInasistencia ? 0m : resultado.Definitiva;
        var propios = new[] { definitiva };
        var otros = new[] { resultado.Asignatura.Cortes.Corte1, resultado.Asignatura.Cortes.Corte2, resultado.Asignatura.Cortes.Corte3, resultado.Acumulada?.Valor };
        return (soloDefinitiva ? propios : propios.Concat(otros)).OfType<decimal>();
    }

    private static readonly HashSet<string> PalabrasDeReferencia = new(StringComparer.Ordinal)
    {
        "seccion", "secciones", "articulo", "articulos", "art"
    };

    [GeneratedRegex(@"(?:^| )necesitas(?: (?:una|la))? definitiva de\z", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex RequisitoPrevio();

    [GeneratedRegex(@"^[\s:=(]*\z", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex SeparadoresDePar();

    [GeneratedRegex(@"^\d\.\d{1,2}\z", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex CifraDeNota();

    private sealed record AtribucionDeDefinitiva(string Clave, string Cifra, int InicioDeAsignatura, string Escrita, bool ConDefinitiva);
}
using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal sealed record CierreEvaluado(
    string Texto,
    IReadOnlyList<Cita> Citas,
    ResultadoAuditoria Resultado,
    bool? UsoDatos,
    bool Bloqueado,
    string? MotivoDeReintento)
{
    public static CierreEvaluado Entregable(string texto, IReadOnlyList<Cita> citas, ResultadoAuditoria resultado, bool? usoDatos = null) =>
        new(texto, citas, resultado, usoDatos, false, null);
}

internal sealed class CierreDeRespuesta
{
    private readonly IBaseConocimiento _baseConocimiento;
    private readonly PoliticaAcceso _politicaAcceso;
    private readonly VerificadorSalida _verificadorSalida;
    private readonly ConfiguracionAsistente _configuracion;
    private readonly CitasDeRespuesta _citasDeRespuesta;
    private readonly CitasDeReglasAplicadas _citasDeReglas;
    private readonly AfirmacionesDePerdida _afirmacionesDePerdida;
    private readonly DefinitivaPorAsignatura _definitivaPorAsignatura;
    private readonly AfirmacionesDeEstado _afirmacionesDeEstado;

    public CierreDeRespuesta(
        IBaseConocimiento baseConocimiento,
        PoliticaAcceso politicaAcceso,
        VerificadorSalida verificadorSalida,
        ConfiguracionAsistente configuracion)
    {
        _baseConocimiento = baseConocimiento;
        _politicaAcceso = politicaAcceso;
        _verificadorSalida = verificadorSalida;
        _configuracion = configuracion;
        _citasDeRespuesta = new CitasDeRespuesta(configuracion.ApoyoMinimoRespaldo);
        _definitivaPorAsignatura = new DefinitivaPorAsignatura(configuracion.Catalogo);
        _citasDeReglas = new CitasDeReglasAplicadas(baseConocimiento, _definitivaPorAsignatura);
        _afirmacionesDePerdida = new AfirmacionesDePerdida(configuracion.Catalogo);
        _afirmacionesDeEstado = new AfirmacionesDeEstado(configuracion.Catalogo);
    }

    public CierreEvaluado Evaluar(SesionPregunta sesion, string texto, EntradaConversacion entrada)
    {
        var propio = IntroduccionDelModelo(sesion, texto);
        if (propio.Trim() == Textos.SinInformacion)
        {
            return SinIntroduccion(sesion, entrada);
        }

        var escritas = EscritasValidas(sesion, propio, entrada);
        var limpio = Limpiar(propio, escritas);
        return ReferenciasEscritas.TieneContenido(limpio) || HayFuga(sesion, limpio, entrada)
            ? Verificar(sesion, limpio, escritas, entrada)
            : SinIntroduccion(sesion, entrada);
    }

    private static string IntroduccionDelModelo(SesionPregunta sesion, string texto) =>
        sesion.Desglose is null ? texto : IntroduccionDelDesglose.SinCifras(texto);

    private static string Limpiar(string texto, IReadOnlyList<Cita> escritas) =>
        Textos.CitasDeTextoFijo(texto) is null ? ReferenciasEscritas.Limpiar(texto, escritas) : texto;

    private CierreEvaluado SinIntroduccion(SesionPregunta sesion, EntradaConversacion entrada) =>
        sesion.Desglose is null
            ? CierreEvaluado.Entregable(Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion)
            : Completar(sesion, string.Empty, [], entrada);

    private bool HayFuga(SesionPregunta sesion, string limpio, EntradaConversacion entrada) =>
        DetectorFugaConfiguracion.HayFuga(limpio, Confidencial(sesion, entrada), sesion.Registro.Fuentes);

    private IReadOnlyList<Cita> EscritasValidas(SesionPregunta sesion, string texto, EntradaConversacion entrada)
    {
        var usadas = _citasDeReglas.Usadas(sesion.Registro, ExtractorCitas.SinCitas(texto), sesion.Directorio);
        return _verificadorSalida.DescartarCitasInexistentes(
            _citasDeRespuesta.EscritasConApoyo(texto, entrada.Secciones, sesion.Registro.Reglas, usadas),
            _baseConocimiento);
    }

    private CierreEvaluado Verificar(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, EntradaConversacion entrada)
    {
        var autorizados = _politicaAcceso.IdsPersonasAutorizadas(sesion.Entrada.Usuario, sesion.Directorio);
        var verificada = VerificarSalida(sesion, limpio, escritas, autorizados, entrada);
        if (verificada.Resultado != ResultadoAuditoria.Respondida)
        {
            return new CierreEvaluado(verificada.Respuesta, verificada.Citas, verificada.Resultado, null, true, verificada.MotivoDeReintento);
        }

        var motivo = MotivoDeAfirmacionNoVerificable(sesion, limpio, autorizados);
        return motivo is null
            ? Completar(sesion, limpio, escritas, entrada)
            : new CierreEvaluado(Textos.NoVerificable, [], ResultadoAuditoria.EstadoNoVerificado, null, true, motivo);
    }

    private SalidaVerificada VerificarSalida(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, IReadOnlyCollection<string> autorizados, EntradaConversacion entrada) =>
        _verificadorSalida.Verificar(
            sesion.Entrada.Usuario,
            limpio,
            escritas,
            autorizados,
            sesion.Registro.Fuentes,
            _baseConocimiento,
            sesion.Directorio,
            Confidencial(sesion, entrada));

    private string? MotivoDeAfirmacionNoVerificable(SesionPregunta sesion, string respuesta, IReadOnlyCollection<string> autorizados)
    {
        var usuario = sesion.Entrada.Usuario;
        var bloques = BloquesDeRespuesta.De(respuesta);
        var resumenes = sesion.Registro.Resumenes;
        var contexto = new ContextoDeAfirmaciones(usuario, autorizados, sesion.Directorio, resumenes);
        return _afirmacionesDePerdida.Motivo(bloques, usuario, autorizados, sesion.Directorio, resumenes)
            ?? _afirmacionesDeEstado.Motivos(bloques, contexto)
            ?? _definitivaPorAsignatura.Motivo(bloques, usuario, autorizados, sesion.Directorio, resumenes)
            ?? CamposLigados.Motivo(bloques, contexto);
    }

    private CierreEvaluado Completar(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, EntradaConversacion entrada)
    {
        var citasDeTextoFijo = Textos.CitasDeTextoFijo(limpio);
        if (citasDeTextoFijo is not null)
        {
            return CierreEvaluado.Entregable(limpio, citasDeTextoFijo, ResultadoAuditoria.Respondida);
        }

        var completo = ConDesglose(sesion, limpio);
        var documentos = CitasDeDocumento(sesion, completo, escritas, entrada);
        if (documentos.Count == 0 && !sesion.Registro.UsoDatos)
        {
            return new CierreEvaluado(Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion, false, true, null);
        }

        IReadOnlyList<Cita> citas = [.. documentos.Concat(sesion.Registro.Citas).Distinct()];
        return CierreEvaluado.Entregable(completo, citas, ResultadoAuditoria.Respondida);
    }

    private static string ConDesglose(SesionPregunta sesion, string introduccion) =>
        sesion.Desglose is not { } desglose
            ? introduccion
            : introduccion.Length == 0 ? desglose : $"{introduccion}\n\n{desglose}";

    private IReadOnlyList<Cita> CitasDeDocumento(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, EntradaConversacion entrada)
    {
        var usadas = _citasDeReglas.Usadas(sesion.Registro, limpio, sesion.Directorio);
        var vigentes = escritas.Where(cita => !sesion.Registro.Reglas.Contains(cita) || usadas.Contains(cita)).ToList();
        var reglas = _citasDeReglas.De(usadas, sesion.Entrada.Pregunta, vigentes);
        IReadOnlyList<Cita> sinRespaldo = [.. vigentes.Concat(reglas).Concat(_citasDeRespuesta.PorTema(limpio, entrada.Secciones)).Distinct()];
        return sinRespaldo.Count > 0 || sesion.Registro.UsoDatos ? sinRespaldo : _citasDeRespuesta.Respaldo(limpio, entrada.Secciones);
    }

    private MaterialConfidencial Confidencial(SesionPregunta sesion, EntradaConversacion entrada) =>
        new(
            _configuracion.MarcadorCanario,
            [ConstructorPrompts.Instrucciones(entrada.PromptSistema), .. DescripcionesDeHerramientas(sesion.Entrada.Usuario.Rol)],
            HerramientasAsistente.NombresInternos);

    private static IEnumerable<string> DescripcionesDeHerramientas(Rol rol) =>
        HerramientasAsistente.Definir(rol)
            .SelectMany(herramienta => herramienta.Parametros.Select(parametro => parametro.Descripcion).Prepend(herramienta.Descripcion));
}
namespace TutorFlow.Api;

public sealed record ResultadoTasa(bool Permitido, int SegundosParaReintentar, bool IniciaBloqueo = false);

public sealed class LimitadorTasaPorIp
{
    private const int UmbralDePurga = 1_000;
    private const int SegundosEntrePurgas = 10;
    private const int SegundosDeVentana = 60;
    private const int SegundosDeReinicio = 600;
    private const int SegundosDelPrimerBloqueo = 30;
    private const int NivelMaximo = 3;

    private static readonly TimeSpan Ventana = TimeSpan.FromSeconds(SegundosDeVentana);
    private static readonly TimeSpan Reinicio = TimeSpan.FromSeconds(SegundosDeReinicio);
    private static readonly TimeSpan EntrePurgas = TimeSpan.FromSeconds(SegundosEntrePurgas);

    private readonly Lock _candado = new();
    private readonly Dictionary<string, EstadoDeIp> _porIp = [];
    private readonly int _limite;
    private readonly TimeProvider _tiempo;
    private long? _ultimaPurga;

    public LimitadorTasaPorIp(int limite, TimeProvider tiempo)
    {
        _limite = limite;
        _tiempo = tiempo;
    }

    public ResultadoTasa Intentar(string ip)
    {
        lock (_candado)
        {
            var ahora = _tiempo.GetTimestamp();
            PurgarSiHaceFalta(ahora);
            if (!_porIp.TryGetValue(ip, out var estado))
            {
                estado = new EstadoDeIp();
                _porIp[ip] = estado;
            }

            return Decidir(estado, ahora);
        }
    }

    private ResultadoTasa Decidir(EstadoDeIp estado, long ahora)
    {
        if (estado.EstaBloqueada(_tiempo, ahora))
        {
            return new ResultadoTasa(false, estado.SegundosRestantes(_tiempo, ahora));
        }

        estado.DescartarMarcasFueraDeVentana(_tiempo, ahora);
        if (estado.Marcas.Count < _limite)
        {
            estado.Marcas.Enqueue(ahora);
            return new ResultadoTasa(true, 0);
        }

        return Bloquear(estado, ahora);
    }

    private ResultadoTasa Bloquear(EstadoDeIp estado, long ahora)
    {
        estado.Marcas.Clear();
        var reinicia = estado.TiempoDesdeElFinDelUltimoBloqueo(_tiempo, ahora) is not { } transcurrido || transcurrido >= Reinicio;
        estado.Nivel = reinicia ? 1 : Math.Min(estado.Nivel + 1, NivelMaximo);
        var duracion = SegundosDelPrimerBloqueo << (estado.Nivel - 1);
        estado.IniciarBloqueo(ahora, TimeSpan.FromSeconds(duracion));
        return new ResultadoTasa(false, duracion, true);
    }

    private void PurgarSiHaceFalta(long ahora)
    {
        if (_porIp.Count < UmbralDePurga || !HayQuePurgar(ahora))
        {
            return;
        }

        _ultimaPurga = ahora;
        foreach (var (ip, estado) in _porIp)
        {
            if (estado.EstaInactivo(_tiempo, ahora))
            {
                _porIp.Remove(ip);
            }
        }
    }

    private bool HayQuePurgar(long ahora) =>
        _ultimaPurga is not { } anterior || _tiempo.GetElapsedTime(anterior, ahora) >= EntrePurgas;

    private sealed class EstadoDeIp
    {
        private long? _inicioDelBloqueo;
        private TimeSpan _duracionDelBloqueo;

        public Queue<long> Marcas { get; } = new();

        public int Nivel { get; set; }

        public void IniciarBloqueo(long ahora, TimeSpan duracion)
        {
            _inicioDelBloqueo = ahora;
            _duracionDelBloqueo = duracion;
        }

        public bool EstaBloqueada(TimeProvider tiempo, long ahora) =>
            _inicioDelBloqueo is { } inicio && tiempo.GetElapsedTime(inicio, ahora) < _duracionDelBloqueo;

        public int SegundosRestantes(TimeProvider tiempo, long ahora) =>
            Math.Max(1, (int)Math.Ceiling((_duracionDelBloqueo - tiempo.GetElapsedTime(_inicioDelBloqueo!.Value, ahora)).TotalSeconds));

        public TimeSpan? TiempoDesdeElFinDelUltimoBloqueo(TimeProvider tiempo, long ahora) =>
            _inicioDelBloqueo is { } inicio ? tiempo.GetElapsedTime(inicio, ahora) - _duracionDelBloqueo : null;

        public void DescartarMarcasFueraDeVentana(TimeProvider tiempo, long ahora)
        {
            while (Marcas.Count > 0 && tiempo.GetElapsedTime(Marcas.Peek(), ahora) >= Ventana)
            {
                Marcas.Dequeue();
            }
        }

        public bool EstaInactivo(TimeProvider tiempo, long ahora)
        {
            DescartarMarcasFueraDeVentana(tiempo, ahora);
            var desdeElFin = TiempoDesdeElFinDelUltimoBloqueo(tiempo, ahora);
            return Marcas.Count == 0 && (desdeElFin is null || desdeElFin >= Reinicio);
        }
    }
}

