namespace TutorFlow.Core.Autorizacion;

internal static class ConteoDeExistencia
{
    private const int MaximoDeRellenoDelConteo = 2;
    private const int MaximoEntreVerboYEstado = 2;
    private const int SinRelleno = 0;
    private const int SinPalabrasEntre = 0;

    public static bool Hay(FrasesDelTexto frases) =>
        frases.Ocurrencias(VocabularioAgregados.Contadores)
            .SelectMany(contador => frases.FinesTrasRelleno(
                contador.Fin, VocabularioAgregados.RellenosDelConteo, MaximoDeRellenoDelConteo, VocabularioAgregados.Grupo))
            .SelectMany(finDelGrupo => frases.FinesTrasRelleno(
                finDelGrupo, [], SinRelleno, VocabularioAgregados.VerbosDeExistencia))
            .Any(finDelVerbo => EsExistenciaDeEstado(frases, finDelVerbo));

    private static bool EsExistenciaDeEstado(FrasesDelTexto frases, int finDelVerbo) =>
        !frases.HayDestinoEnLosSiguientes(finDelVerbo, SinPalabrasEntre, VocabularioAgregados.Derecho)
        && frases.HayDestinoEnLosSiguientes(finDelVerbo, MaximoEntreVerboYEstado, VocabularioAgregados.Estados);
}
namespace TutorFlow.Core.Autorizacion;

internal readonly record struct OcurrenciaDeFrase(int Inicio, int Fin);

internal sealed class FrasesDelTexto(string textoNormalizado)
{
    private readonly IReadOnlyList<string> _palabras = TokenizadorTexto.Valores(textoNormalizado);

    public bool Contiene(IEnumerable<string> frases) =>
        frases.Any(frase => Posiciones(frase).Any());

    public bool ContieneRaiz(string raiz) =>
        _palabras.Any(palabra => palabra.StartsWith(raiz, StringComparison.Ordinal));

    public bool ContieneSeguidaDe(IEnumerable<string> frases, IReadOnlyCollection<string> siguientes) =>
        frases.Any(frase => Posiciones(frase).Any(posicion => EmpiezaAlgunaEn(posicion + Palabras(frase).Length, siguientes)));

    public IReadOnlyList<OcurrenciaDeFrase> Ocurrencias(IEnumerable<string> frases) =>
        [.. frases.SelectMany(frase => Posiciones(frase).Select(posicion => new OcurrenciaDeFrase(posicion, posicion + Palabras(frase).Length)))];

    public string PalabraAntesDe(OcurrenciaDeFrase ocurrencia) =>
        Palabra(ocurrencia.Inicio - 1);

    public bool SeguidaDeRellenoY(IEnumerable<string> frases, IReadOnlyCollection<string> rellenos, int maximoDeRelleno, IReadOnlyCollection<string> destinos) =>
        Ocurrencias(frases).Any(ocurrencia => LlegaAlDestino(ocurrencia.Fin, rellenos, maximoDeRelleno, destinos));

    public IEnumerable<int> FinesTrasRelleno(int indice, IReadOnlyCollection<string> rellenos, int maximoDeRelleno, IReadOnlyCollection<string> destinos) =>
        Enumerable.Range(0, maximoDeRelleno + 1)
            .Where(relleno => Enumerable.Range(0, relleno).All(salto => rellenos.Contains(Palabra(indice + salto))))
            .SelectMany(relleno => destinos.Where(destino => EmpiezaEn(indice + relleno, destino))
                .Select(destino => indice + relleno + Palabras(destino).Length));

    public bool HayDestinoEnLosSiguientes(int indice, int maximoEntre, IReadOnlyCollection<string> destinos) =>
        Enumerable.Range(0, maximoEntre + 1).Any(entre => EmpiezaAlgunaEn(indice + entre, destinos));

    private bool LlegaAlDestino(int indice, IReadOnlyCollection<string> rellenos, int maximoDeRelleno, IReadOnlyCollection<string> destinos) =>
        FinesTrasRelleno(indice, rellenos, maximoDeRelleno, destinos).Any();

    public IReadOnlyList<string> PalabrasDesde(int indice) =>
        [.. _palabras.Skip(Math.Max(indice, 0))];

    private string Palabra(int indice) =>
        indice >= 0 && indice < _palabras.Count ? _palabras[indice] : string.Empty;

    private static string[] Palabras(string frase) => frase.Split(' ');

    private bool EmpiezaAlgunaEn(int indice, IEnumerable<string> frases) =>
        frases.Any(frase => EmpiezaEn(indice, frase));

    private IEnumerable<int> Posiciones(string frase) =>
        Enumerable.Range(0, _palabras.Count).Where(indice => EmpiezaEn(indice, frase));

    private bool EmpiezaEn(int indice, string frase)
    {
        var palabras = Palabras(frase);
        return indice + palabras.Length <= _palabras.Count
            && palabras.Select((palabra, desplazamiento) => _palabras[indice + desplazamiento] == palabra).All(coincide => coincide);
    }
}
namespace TutorFlow.Core.Autorizacion;

internal static class ProximidadDeFrases
{
    public static bool Hay(IEnumerable<OcurrenciaDeFrase> primeras, IReadOnlyCollection<OcurrenciaDeFrase> segundas, int maximoEntre) =>
        primeras.Any(primera => Cercanas(primera, segundas, maximoEntre));

    public static bool Cercanas(OcurrenciaDeFrase primera, IEnumerable<OcurrenciaDeFrase> segundas, int maximoEntre) =>
        segundas.Any(segunda => PalabrasEntre(primera, segunda) is >= 0 and var entre && entre <= maximoEntre);

    private static int PalabrasEntre(OcurrenciaDeFrase primera, OcurrenciaDeFrase segunda)
    {
        if (segunda.Inicio >= primera.Fin)
        {
            return segunda.Inicio - primera.Fin;
        }

        return primera.Inicio >= segunda.Fin ? primera.Inicio - segunda.Fin : -1;
    }
}
using System.Text;

namespace TutorFlow.Core.Autorizacion;

internal static class CoincidenciaSinEspacios
{
    public const int MinimoLetrasDelNombre = 8;

    public static bool Aplica(IReadOnlyList<string> nombre) =>
        nombre.Sum(token => token.Length) >= MinimoLetrasDelNombre;

    public static IEnumerable<(int Primero, int Ultimo)> Buscar(IReadOnlyList<TokenTexto> tokens, string objetivo) =>
        Enumerable.Range(0, tokens.Count)
            .Select(inicio => (Primero: inicio, Ultimo: UltimoQueCompleta(tokens, inicio, objetivo)))
            .Where(tramo => tramo.Ultimo >= 0);

    private static int UltimoQueCompleta(IReadOnlyList<TokenTexto> tokens, int inicio, string objetivo)
    {
        var acumulado = new StringBuilder();
        for (var indice = inicio; indice < tokens.Count && acumulado.Length < objetivo.Length; indice++)
        {
            acumulado.Append(tokens[indice].Valor);
            if (acumulado.Length == objetivo.Length && acumulado.ToString() == objetivo)
            {
                return indice;
            }
        }

        return -1;
    }
}
